  "constructions": [
    {
      "name": "Research.Horner.P",
      "description": "P : List(R) x R -> R. For every x in R, P([],x) = 0. For every a in R and finite real list t, P(a::t,x) = a + x P(t,x). Thus for c = [a_0,...,a_(n-1)], where n is any nonnegative integer, P(c,x) = sum over integers i with 0 <= i < n of a_i x^i, with empty sum 0. The first coefficient is the constant coefficient. All operations are exact real operations."
    },
